args.old_str:
BOOL will_word_fit(LPCSTR text, FLOAT width, LPCFONT font) {
    for (LPCSTR p = text; *p && !isspace(*p) && *p != '|';) {
        unsigned codepoint;
        p = utf8_to_codepoint(p, &codepoint);
        glyphSet_t *set = R_GetGlyphSet((LPFONT)font, codepoint);
        stbtt_bakedchar *g = &set->glyphs[codepoint & 0xff];
        width -= INV_SCALE_X(g->xadvance);
    }
    return width >= -0.001;
}

args.new_str:
BOOL will_word_fit(LPCSTR text, FLOAT width, LPCFONT font) {
    for (LPCSTR p = text; *p && !isspace(*p) && *p != '|';) {
        unsigned codepoint;
        p = utf8_to_codepoint(p, &codepoint);

        // 计算宽度不需要纹理，传入 FALSE
        glyphSet_t *set = R_GetGlyphSet((LPFONT)font, codepoint, FALSE);
        stbtt_bakedchar *g = &set->glyphs[codepoint & 0xff];

        // 检查 glyph 是否有效
        if (g->x1 > g->x0) {
            width -= INV_SCALE_X(g->xadvance);
        } else {
            width -= INV_SCALE_X(((LPFONT)font)->size * 0.5);
        }

        if (width < -0.001) return FALSE;
    }
    return width >= -0.001;
}
